/*
 * A379116  Numbers k for which A328845(k) is a multiple of 5, where A328845
 *          is the first Fibonacci based variant of arithmetic derivative.
 * https://oeis.org/A379116
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 85, u16 n <= 9856, u32 n <= 9856, u64 n <= 9856,
 *            u128 n <= 9856, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: a(n) = the n-th integer k such that A328845(k) is a multiple of 5.
 * The values are generated by a sieve that tests the Fibonacci based
 * arithmetic derivative for each integer.
 *
 * Numerical definition of the derivative d(n):
 *   d(1) = 0
 *   d(p) = F_p            (Fibonacci number with index p)
 *   d(mn) = m*d(n) + n*d(m)
 *
 * From this follows the closed formula:
 *   d(n) = n * Σ_{p^e‖n} (e * F_p / p).
 * Hence d(n) ≡ 0 (mod 5) iff either 5 | n or
 *        Σ (e * F_p / p) ≡ 0 (mod 5) (for n not divisible by 5).
 * The program precomputes Fibonacci numbers modulo 5 using the period 20,
 * stores smallest prime factors up to the current bound via a sieve,
 * and then scans integers in increasing order until the requested index
 * is reached.
 */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Smallest prime factor table and primitive data */
static uint32_t *spf = NULL;          /* spf[i] == smallest prime factor of i */
static idx_t spf_limit = 0;           /* current maximum for spf table */

/* Sequence cache (0-indexed: seq_cache[0] corresponds to a(1)) */
static seq_t *seq_cache = NULL;
static size_t seq_len = 0;            /* number of cached terms */
static size_t seq_cap = 0;            /* allocated capacity of seq_cache */
static idx_t cur_candidate = 2;       /* next number to test */

/* Fibonacci numbers modulo 5 (period 20) */
static const unsigned char fib_mod5[20] =
{
    0,1,1,2,3,0,3,3,1,4,0,4,4,3,2,0,2,2,4,1
};
/* Multiplicative inverses modulo 5 for numbers 1–4 */
static const unsigned char inv_mod5[5] = {0,1,3,2,4};

/* Build spf table up to at least 'n' */
static void build_spf(idx_t n)
{
    idx_t new_lim = (spf_limit>0? spf_limit*2: 64);
    while (new_lim < n) new_lim <<= 1;
    spf = (uint32_t*)realloc(spf, (new_lim+1)*sizeof(uint32_t));
    for (idx_t i=0; i<=new_lim; ++i) spf[i] = 0;
    for (idx_t i=2; i<=new_lim; ++i)
    {
        if (spf[i] == 0)
        {
            spf[i] = (uint32_t)i;
            if (i*i <= new_lim)
            {
                for (idx_t j=i*i; j<=new_lim; j+=i)
                    if (spf[j] == 0) spf[j] = (uint32_t)i;
            }
        }
    }
    spf_limit = new_lim;
}

/* Check whether the Fibonacci based arithmetic derivative of x is a multiple of 5 */
static bool is_good(idx_t x)
{
    if (x == 0 || x == 1) return true;     /* d(0)=d(1)=0 */
    if (x % 5 == 0) return true;            /* any multiple of 5 qualifies */

    idx_t temp = x;
    unsigned char sum = 0;

    while (temp > 1)
    {
        uint32_t p = spf[temp];
        if (p == 0) p = (uint32_t)temp;    /* safety for primes beyond table */
        idx_t e = 0;
        while (temp % p == 0)
        {
            temp /= p;
            ++e;
        }
        unsigned char e_mod5 = (unsigned char)(e % 5);
        unsigned char fp = fib_mod5[p % 20];
        unsigned char inv = inv_mod5[p % 5];
        unsigned char term = ((e_mod5 * fp) % 5) * inv % 5;
        sum += term;
        if (sum >= 5) sum -= 5;
    }
    return sum == 0;
}

/* Ensure that the cache contains at least 'n' terms */
static void ensure_cache(idx_t n)
{
    if (seq_len == 0)                          /* first time initialization */
    {
        seq_cap = 16;
        seq_cache = (seq_t*)malloc(seq_cap * sizeof(seq_t));
        seq_cache[0] = (seq_t)0;              /* a(1) = 0 */
        seq_cache[1] = (seq_t)1;              /* a(2) = 1 */
        seq_len = 2;
        cur_candidate = 2;
    }

    while (seq_len < n)
    {
        if (cur_candidate > spf_limit) build_spf(cur_candidate);

        if (is_good(cur_candidate))
        {
            if (seq_len >= seq_cap)
            {
                seq_cap = seq_cap ? seq_cap * 2 : 16;
                seq_cache = (seq_t*)realloc(seq_cache, seq_cap * sizeof(seq_t));
            }
            seq_cache[seq_len] = (seq_t)cur_candidate;
            ++seq_len;
        }
        ++cur_candidate;
    }
}

/* Public function required by the build */
seq_t a(idx_t n)
{
    ensure_cache(n);
    return seq_cache[n - 1];
}
